insert into public.sc_services (code, slug, position, title, short_title, card_description, action_label, icon_key, accent_key, featured, has_detail_page, title_lead, title_accent, category, visual_label, art_key, summary, overview, important_note, seo_title, seo_description, published) values ('S03', 'passport-photos', 3, 'Passport Photographs & Picture Printing', 'Passport Photos', 'Passport photographs and quality picture printing for personal, school and professional needs.', 'Ask about photos', 'Camera', 'photo', false, true, 'Passport photos,', 'ready for your next step.', 'PHOTO & PRINT SERVICES', 'PHOTO / PRINT', 'passport', 'Need passport-style photographs or a printed picture? Visit Supreme Computer for help with the photo and printing process.', 'Whether your photograph is for an application, school record or personal use, our team can help you discuss the right print format and prepare your picture.', 'Photo requirements differ by institution and application. Please confirm the exact specification with the requesting organisation; acceptance cannot be guaranteed by the print service.', 'Passport Photographs & Picture Printing | Supreme Computer', 'Learn about passport-style photographs and picture printing at Supreme Computer in Akpata, Benin City. Confirm formats, availability and pricing by phone.', true) on conflict (code) do update set slug = excluded.slug, position = excluded.position, title = excluded.title, short_title = excluded.short_title, card_description = excluded.card_description, action_label = excluded.action_label, icon_key = excluded.icon_key, accent_key = excluded.accent_key, featured = excluded.featured, has_detail_page = excluded.has_detail_page, title_lead = excluded.title_lead, title_accent = excluded.title_accent, category = excluded.category, visual_label = excluded.visual_label, art_key = excluded.art_key, summary = excluded.summary, overview = excluded.overview, important_note = excluded.important_note, seo_title = excluded.seo_title, seo_description = excluded.seo_description, published = excluded.published;
insert into public.sc_services (code, slug, position, title, short_title, card_description, action_label, icon_key, accent_key, featured, has_detail_page, title_lead, title_accent, category, visual_label, art_key, summary, overview, important_note, seo_title, seo_description, published) values ('S04', 'print-from-phone', 4, 'Printing From Your Phone', 'Print From Your Phone', 'Have a file on your phone? Contact our team to arrange convenient, professional printing.', 'Ask how it works', 'Smartphone', 'phone', false, true, 'Your file. Your phone.', 'Printed with care.', 'CONVENIENT DOCUMENT PRINTING', 'SEND / PRINT', 'phone', 'Have a document on your phone? Supreme Computer can help you arrange printing without needing to bring a laptop.', 'From documents and application forms to everyday pages, start by telling our team what you need printed. We will confirm how to provide the file and discuss the available print options.', 'This website does not accept document uploads. Please agree on a file-sharing method directly with staff, and avoid sending sensitive identification or private account details unless necessary and appropriate.', 'Print From Your Phone | Supreme Computer', 'Learn about printing documents from your phone at Supreme Computer in Benin City. Confirm file transfer options and pricing by phone.', true) on conflict (code) do update set slug = excluded.slug, position = excluded.position, title = excluded.title, short_title = excluded.short_title, card_description = excluded.card_description, action_label = excluded.action_label, icon_key = excluded.icon_key, accent_key = excluded.accent_key, featured = excluded.featured, has_detail_page = excluded.has_detail_page, title_lead = excluded.title_lead, title_accent = excluded.title_accent, category = excluded.category, visual_label = excluded.visual_label, art_key = excluded.art_key, summary = excluded.summary, overview = excluded.overview, important_note = excluded.important_note, seo_title = excluded.seo_title, seo_description = excluded.seo_description, published = excluded.published;
insert into public.sc_services (code, slug, position, title, short_title, card_description, action_label, icon_key, accent_key, featured, has_detail_page, title_lead, title_accent, category, visual_label, art_key, summary, overview, important_note, seo_title, seo_description, published) values ('S05', 'nin-assistance', 5, 'NIN Registration Assistance', 'NIN Assistance', 'Guidance with NIN registration-related processes, subject to applicable official requirements.', 'Ask for guidance', 'IdCard', 'id', false, true, 'NIN assistance,', 'clearly explained.', 'REGISTRATION-RELATED GUIDANCE', 'NIN / GUIDANCE', 'nin', 'Get practical assistance with NIN registration-related questions and processes, subject to applicable official requirements.', 'NIN processes can involve specific instructions and authorised channels. Supreme Computer can discuss the assistance currently available and help you understand what to check before proceeding.', 'Supreme Computer provides assistance only. NIN registration, identity verification and issuance are governed by the relevant Nigerian authorities and their authorised processes. Do not submit your NIN or identity documents through the website contact form.', 'NIN Registration Assistance | Supreme Computer', 'Get practical assistance with NIN registration-related processes at Supreme Computer in Benin City. Confirm requirements and availability by phone.', true) on conflict (code) do update set slug = excluded.slug, position = excluded.position, title = excluded.title, short_title = excluded.short_title, card_description = excluded.card_description, action_label = excluded.action_label, icon_key = excluded.icon_key, accent_key = excluded.accent_key, featured = excluded.featured, has_detail_page = excluded.has_detail_page, title_lead = excluded.title_lead, title_accent = excluded.title_accent, category = excluded.category, visual_label = excluded.visual_label, art_key = excluded.art_key, summary = excluded.summary, overview = excluded.overview, important_note = excluded.important_note, seo_title = excluded.seo_title, seo_description = excluded.seo_description, published = excluded.published;
insert into public.sc_services (code, slug, position, title, short_title, card_description, action_label, icon_key, accent_key, featured, has_detail_page, title_lead, title_accent, category, visual_label, art_key, summary, overview, important_note, seo_title, seo_description, published) values ('S06', 'waec-neco', 6, 'WAEC & NECO Services', 'WAEC & NECO Services', 'Assistance checking examination results and scratch cards where available. Call to confirm details.', 'Check availability', 'FileText', 'exam', false, true, 'Exam results,', 'less hassle.', 'EXAMINATION SUPPORT', 'WAEC / NECO', 'exams', 'Ask for assistance checking WAEC and NECO examination results, plus scratch cards when available.', 'If you need help navigating a result-checking process or want to ask about examination scratch cards, Supreme Computer can confirm its current services and availability.', 'Results are provided by the examination bodies, not Supreme Computer. Scratch cards or tokens may be unavailable, and the centre cannot change examination outcomes. Do not submit candidate credentials or PINs through this website.', 'WAEC & NECO Result Services | Supreme Computer', 'Ask for assistance checking WAEC and NECO examination results at Supreme Computer in Benin City. Confirm scratch card availability and pricing by phone.', true) on conflict (code) do update set slug = excluded.slug, position = excluded.position, title = excluded.title, short_title = excluded.short_title, card_description = excluded.card_description, action_label = excluded.action_label, icon_key = excluded.icon_key, accent_key = excluded.accent_key, featured = excluded.featured, has_detail_page = excluded.has_detail_page, title_lead = excluded.title_lead, title_accent = excluded.title_accent, category = excluded.category, visual_label = excluded.visual_label, art_key = excluded.art_key, summary = excluded.summary, overview = excluded.overview, important_note = excluded.important_note, seo_title = excluded.seo_title, seo_description = excluded.seo_description, published = excluded.published;
insert into public.sc_services (code, slug, position, title, short_title, card_description, action_label, icon_key, accent_key, featured, has_detail_page, title_lead, title_accent, category, visual_label, art_key, summary, overview, important_note, seo_title, seo_description, published) values ('S07', 'computer-training', 7, 'Computer Training', 'Computer Training', 'Build practical computer skills with guided learning. Contact us for current training schedules.', 'Ask about training', 'GraduationCap', 'learn', false, true, 'Build useful skills.', 'Gain confidence.', 'PRACTICAL DIGITAL SKILLS', 'LEARN / PRACTISE', 'training', 'Choose from a 3-month Computer Appreciation course or a 6-month programme covering essential Microsoft Office skills and CorelDRAW.', 'Our 3-month Computer Appreciation course introduces practical computer skills, Microsoft Word and Microsoft Excel. For more advanced training, the 6-month course covers Microsoft Word, Excel, PowerPoint and CorelDRAW. Contact our centre for enrolment information and class schedules.', 'The listed courses run for 3 months and 6 months respectively. Contact Supreme Computer directly to confirm class availability, schedules, fees, enrolment requirements and any certificate arrangements.', 'Computer Training | Supreme Computer', 'Learn about practical computer training at Supreme Computer, Benin City. Ask the centre for current subjects, schedules and fees.', true) on conflict (code) do update set slug = excluded.slug, position = excluded.position, title = excluded.title, short_title = excluded.short_title, card_description = excluded.card_description, action_label = excluded.action_label, icon_key = excluded.icon_key, accent_key = excluded.accent_key, featured = excluded.featured, has_detail_page = excluded.has_detail_page, title_lead = excluded.title_lead, title_accent = excluded.title_accent, category = excluded.category, visual_label = excluded.visual_label, art_key = excluded.art_key, summary = excluded.summary, overview = excluded.overview, important_note = excluded.important_note, seo_title = excluded.seo_title, seo_description = excluded.seo_description, published = excluded.published;
